mapper.select:
select
(select count(*) from STORAGE_CHANGE_DETAIL scd where scd.sc_id=mn.id) as expertCount,
mn.*
from STORAGE_CHANGE mn

    
        and mn.sc_Category=#{params.scCategory}
    
    
        and mn.state=#{params.state}
    
    
        and INSTR(mn.sc_code,#{params.scCode})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
